// The shop sends the drop once with every subscriber; email each one separately
const b = $input.first().json.body || {};
return (b.subscribers || [])
  .filter((s) => s && s.email)
  .map((s) => ({
    json: {
      email: s.email,
      phone: s.phone || '',
      unsubscribeUrl: s.unsubscribeUrl,
      shop: b.businessName || 'our shop',
      title: b.title || 'A new drop',
      description: b.description || '',
      products: b.products || [],
      pickupWindows: b.pickupWindows || [],
      pickupArea: b.pickupArea || '',
      orderCloseAt: b.orderCloseAt || '',
      dropUrl: b.dropUrl || '',
    },
  }));

// Everyone on the list with a phone gets the drop alert by text (email people get the email too).
// The shop marks canText false for anyone who replied STOP and for repeat numbers.
const b = $input.first().json.body || {};
const shop = b.businessName || 'our shop';
return (b.subscribers || [])
  .filter((s) => s && s.phone && s.canText)
  .map((s) => {
    const d = String(s.phone).replace(/\D/g, '');
    const phone = d.length === 10 ? '+1' + d : d.length === 11 && d.startsWith('1') ? '+' + d : '+' + d;
    const message = b.smsMessage || (shop + ': ' + (b.title || 'A new drop') + ' is open for orders! ' + (b.dropUrl || '') + (b.orderCloseAt ? ' Orders close ' + b.orderCloseAt + '.' : '') + ' Reply STOP to opt out.');
    return { json: { phone, message } };
  });

// The shop lists who gets a text (people who haven't ordered, didn't reply STOP)
const b = $input.first().json.body || {};
return (b.texts || []).map((t) => {
  const d = String(t.phone).replace(/\D/g, '');
  const phone = d.length === 10 ? '+1' + d : d.length === 11 && d.startsWith('1') ? '+' + d : '+' + d;
  return { json: { phone, message: b.smsMessage } };
});

// People with no phone (or who replied STOP to texts) get an email instead
const b = $input.first().json.body || {};
return (b.emails || []).map((e) => ({
  json: {
    email: e.email,
    unsubscribeUrl: e.unsubscribeUrl,
    shop: b.businessName || 'our shop',
    title: b.title || 'This drop',
    orderCloseAt: b.orderCloseAt || '',
    dropUrl: b.dropUrl || '',
  },
}));
